from django.shortcuts import get_object_or_404, render

from .models import Article  # your model


def home(request):
    return render(request, "home.html")


def article_detail(request, slug):
    # Unknown slug -> Http404 before any output is produced (RTE-005/006).
    article = get_object_or_404(Article, slug=slug, published=True)
    return render(request, "article.html", {"article": article})
### file: core/errors.py
from django.db import InterfaceError, OperationalError
from django.shortcuts import render

COPY = {
    404: ("Page not found", "That page does not exist or has moved."),
    410: ("Page removed", "This page has been permanently removed."),
    500: ("Something went wrong", "We hit a problem on our side. Please try again shortly."),
    503: ("Temporarily unavailable", "The service is busy or down for maintenance. Please try again shortly."),
}


def error_page(request, status):
    title, message = COPY[status]
    return render(request, "error.html", {"title": title, "message": message}, status=status)


def not_found(request, exception=None):
    return error_page(request, 404)


def server_error(request):
    return error_page(request, 500)


def gone(request, *args, **kwargs):
    return error_page(request, 410)


class DependencyDown:
    """Database unreachable while a view runs -> 503 page (RTE-007)."""

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        return self.get_response(request)

    def process_exception(self, request, exception):
        if isinstance(exception, (OperationalError, InterfaceError)):
            return error_page(request, 503)
        return None
