from django import forms


class ContactForm(forms.Form):
    name = forms.CharField(max_length=100, widget=forms.TextInput(attrs={"autocomplete": "name"}))
    email = forms.EmailField(max_length=254, widget=forms.EmailInput(attrs={"autocomplete": "email"}))
    message = forms.CharField(max_length=5000, widget=forms.Textarea(attrs={"rows": 6}))
    # Honeypot (SEC-055): not type=hidden, hidden by CSS class "hp"; real visitors leave it empty.
    website = forms.CharField(
        required=False,
        max_length=200,
        label="Leave this field empty",
        widget=forms.TextInput(attrs={"tabindex": "-1", "autocomplete": "off"}),
    )
