import logging
import smtplib

from django.conf import settings
from django.core.cache import cache
from django.core.mail import EmailMessage
from django.http.response import HttpResponseRedirectBase
from django.shortcuts import render
from django.urls import reverse
from django.views.decorators.http import require_http_methods

from .forms import ContactForm

log = logging.getLogger(__name__)
LIMIT, WINDOW = 5, 600  # 5 submissions per 10 minutes per client (SEC-054)


class HttpResponseSeeOther(HttpResponseRedirectBase):
    status_code = 303  # POST -> GET redirect, works without JavaScript


def over_limit(request) -> bool:
    key = f"contact-rl:{request.META.get('REMOTE_ADDR', '')}"  # behind a proxy, fix REMOTE_ADDR at the proxy
    if cache.add(key, 1, timeout=WINDOW):
        return False
    try:
        return cache.incr(key) > LIMIT
    except ValueError:  # key expired between add() and incr()
        cache.add(key, 1, timeout=WINDOW)
        return False


def page(request, form, status=200, error=None):
    return render(request, "contact.html", {"form": form, "error": error}, status=status)


@require_http_methods(["GET", "POST"])
def contact(request):
    if request.method == "GET":
        return page(request, ContactForm())
    if over_limit(request):
        response = page(request, ContactForm(), 429, "Too many messages. Please try again later.")
        response.headers["Retry-After"] = str(WINDOW)
        return response
    if request.POST.get("website"):  # honeypot filled: look successful, cause no side effect
        return HttpResponseSeeOther(reverse("contact_thanks"))
    form = ContactForm(request.POST)
    if not form.is_valid():
        return page(request, form, 400)
    data = form.cleaned_data
    try:
        # DELIVERY: the one block a project replaces (webhook POST, CRM API, database insert).
        sent = EmailMessage(
            subject="New website enquiry",
            body=f"From: {data['name']} <{data['email']}>\n\n{data['message']}",
            from_email=settings.DEFAULT_FROM_EMAIL,
            to=[settings.CONTACT_TO_EMAIL],
            reply_to=[data["email"]],
        ).send()
    except (OSError, smtplib.SMTPException):
        log.exception("contact delivery failed")
        sent = 0
    if sent != 1:  # RES-008: never claim success when delivery failed
        return page(request, form, 503, "We could not send your message. Please try again shortly.")
    return HttpResponseSeeOther(reverse("contact_thanks"))


def thanks(request):
    response = render(request, "contact_thanks.html")
    response.headers["X-Robots-Tag"] = "noindex"  # IDX-016: confirmation page stays out of the index
    return response
