Django 6.x with django.contrib.sitemaps. Mode comes from DEPLOY_ENV only ("production" is the one production value), read from the process environment at request time (nothing is inlined at build). Set SITE_URL=https://example.com. Non-production: robots.txt is Disallow: /, no sitemap (404), X-Robots-Tag: noindex, nofollow on every response including static files.
### file: config/settings.py
INSTALLED_APPS += ["django.contrib.sitemaps"]
MIDDLEWARE.insert(0, "core.seo.NoindexOutsideProduction")  # first = outermost, so static files get the header too
### file: core/seo.py
import os
from urllib.parse import urlsplit

from django.contrib.sitemaps import Sitemap
from django.contrib.sitemaps.views import sitemap
from django.http import Http404, HttpResponse
from django.urls import reverse


def is_production() -> bool:
    return os.environ.get("DEPLOY_ENV") == "production"


def site_url() -> str:
    return os.environ.get("SITE_URL", "https://example.com").rstrip("/")


class NoindexOutsideProduction:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)
        if not is_production():
            response.headers["X-Robots-Tag"] = "noindex, nofollow"  # IDX-005
        return response


def robots_txt(request):
    if is_production():
        # Only app/API/private paths are disallowed, never CSS/JS/images (IDX-004).
        lines = [
            "User-agent: *",
            "Allow: /",
            "Disallow: /admin/",
            "Disallow: /api/",
            f"Sitemap: {site_url()}/sitemap.xml",
        ]
    else:
        lines = ["User-agent: *", "Disallow: /"]  # no Sitemap line
    return HttpResponse("\n".join(lines) + "\n", content_type="text/plain")


class PublicPages(Sitemap):
    protocol = "https"
    limit = 50000  # protocol maximum per file (IDX-002); above it, switch to django.contrib.sitemaps.views.index

    def get_domain(self, site=None):  # canonical host from SITE_URL, not from the request Host header
        return urlsplit(site_url()).netloc

    def items(self):
        # Indexable public pages only (200, canonical, not noindex): url names or model instances.
        return ["home", "contact"]

    def location(self, item):
        return reverse(item)  # same trailing-slash policy as the canonical tags


def sitemap_xml(request):
    if not is_production():
        raise Http404("no sitemap outside production")
    response = sitemap(request, {"pages": PublicPages})
    # Django adds "X-Robots-Tag: noindex, noodp, noarchive" to sitemap responses; production sends no noindex signal.
    if "X-Robots-Tag" in response.headers:
        del response.headers["X-Robots-Tag"]
    return response
